// When does a LabFlow booking end, in minutes since 00:00?
export function endMinute(startMinute, length) {
  return startMinute + length;
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { endMinute } from '../src/end.ts';

test('08:00 + 2 hours ends at minute 600', () => assert.equal(endMinute(480, 120), 600));
test('a 30-minute slot from 20:30 ends at 21:00', () => assert.equal(endMinute(1230, 30), 1260));

